window.AAT_NEWS_BODY = [{"date": "2026-08-04", "source": "https://www.diyinternational.com/content/news/2026/08/04/free/tite-x-iht-launches-global-buyer-invitation-program.html", "body": {"en": ["The Taiwan International Tools & Hardware Expo and International Hardware Expo Taiwan (TiTE x IHT) has launched a Global Buyer Invitation Program. The show runs from October 20 to 22, 2026, at the Taichung International Convention and Exhibition Center (TICEC). It is organised by the Taiwan Hand Tool Manufacturers' Association (THTMA) and Lanza International.", "The program targets international brand owners, retail chains, importers, distributors and corporate buyers with clear sourcing needs. Qualified buyers can receive accommodation subsidies, business matchmaking and factory visits. Under the \"Exhibition as Factory\" idea, buyers can meet suppliers at the show and then visit nearby factories to check production.", "Organisers expect more than 500 exhibitors and over 1,000 booths, covering hand tools, fasteners, precision machinery, metal processing and smart manufacturing. The theme is \"From Manufacturing to Co-Creation\", and an International Buyer Golden Sourcing Week is timed to match the autumn Canton Fair in China."], "ar": ["أطلق معرض تايوان الدولي للأدوات والعُدد ومعرض تايوان الدولي للعُدد (TiTE x IHT) برنامجًا لدعوة المشترين من مختلف أنحاء العالم. ويُقام المعرض من 20 إلى 22 أكتوبر 2026 في مركز تايتشونغ الدولي للمؤتمرات والمعارض (TICEC)، وتنظمه رابطة مصنّعي الأدوات اليدوية في تايوان (THTMA) وشركة Lanza International.", "يستهدف البرنامج أصحاب العلامات التجارية الدولية وسلاسل البيع بالتجزئة والمستوردين والموزعين ومسؤولي المشتريات في الشركات ممن لديهم احتياجات توريد واضحة. ويمكن للمشترين المؤهلين الحصول على دعم للإقامة وخدمات مطابقة الأعمال وزيارات للمصانع. ووفق مفهوم \"المعرض بوصفه مصنعًا\"، يلتقي المشترون بالموردين في المعرض ثم يزورون المصانع القريبة للاطلاع على الإنتاج.", "يتوقع المنظمون مشاركة أكثر من 500 عارض وأكثر من 1,000 جناح، تشمل الأدوات اليدوية والمثبتات والآلات الدقيقة وتشغيل المعادن والتصنيع الذكي. ويحمل المعرض شعار \"من التصنيع إلى الإبداع المشترك\"، كما يتزامن \"أسبوع التوريد الذهبي للمشترين الدوليين\" مع دورة الخريف من معرض كانتون في الصين."], "zh-TW": ["台灣國際工具暨五金展（TiTE x IHT）推出全球買主邀請計畫。展會將於2026年10月20日至22日在台中國際會展中心（TICEC）舉行，由台灣區手工具工業同業公會（THTMA）與Lanza International共同主辦。", "此計畫鎖定具明確採購需求的國際品牌商、大型零售通路、進口商、經銷商及企業採購代表。符合資格的買主可獲得住宿補助、商務媒合及工廠參訪等服務。在「展場即工廠」的概念下，買主可先在展場與供應商洽談，再前往鄰近工廠實地了解生產情況。", "主辦單位預期將有逾500家展商、超過1,000個攤位，涵蓋手工具、扣件、精密機械、金屬加工及智慧製造。本屆主題為「從製造到共創」，並規劃「國際買主黃金採購週」，與中國秋季廣交會的時程相互配合。"], "zh-CN": ["台湾国际工具暨五金展（TiTE x IHT）推出全球买家邀请计划。展会将于2026年10月20日至22日在台中国际会展中心（TICEC）举行，由台湾区手工具工业同业公会（THTMA）与Lanza International共同主办。", "该计划面向具有明确采购需求的国际品牌商、大型零售渠道、进口商、经销商及企业采购代表。符合资格的买家可获得住宿补贴、商务对接及工厂参观等服务。在“展场即工厂”的理念下，买家可先在展会上与供应商洽谈，再前往附近工厂实地了解生产情况。", "主办方预计将有500多家展商、超过1,000个展位，涵盖手工具、紧固件、精密机械、金属加工及智能制造。本届主题为“从制造到共创”，并设立“国际买家黄金采购周”，与中国秋季广交会的时间相配合。"], "ms": ["Taiwan International Tools & Hardware Expo dan International Hardware Expo Taiwan (TiTE x IHT) telah melancarkan Program Jemputan Pembeli Global. Pameran ini akan berlangsung dari 20 hingga 22 Oktober 2026 di Taichung International Convention and Exhibition Center (TICEC), dan dianjurkan oleh Taiwan Hand Tool Manufacturers' Association (THTMA) serta Lanza International.", "Program ini menyasarkan pemilik jenama antarabangsa, rangkaian runcit, pengimport, pengedar dan wakil perolehan syarikat yang mempunyai keperluan sumber yang jelas. Pembeli yang layak boleh menerima subsidi penginapan, padanan perniagaan dan lawatan kilang. Melalui konsep \"Pameran sebagai Kilang\", pembeli boleh bertemu pembekal di pameran dan kemudian melawat kilang berdekatan untuk melihat proses pengeluaran.", "Penganjur menjangkakan lebih 500 pempamer dan lebih 1,000 gerai, meliputi alat tangan, pengikat, jentera kejituan, pemprosesan logam dan pembuatan pintar. Temanya ialah \"Dari Pembuatan kepada Penciptaan Bersama\", dan Minggu Perolehan Emas Pembeli Antarabangsa dijadualkan selaras dengan Canton Fair musim luruh di China."]}}, {"date": "2026-07-04", "source": "https://focustaiwan.tw/sci-tech/202607040007", "body": {"en": ["Taiwan's AI application planner certification, launched in 2025 by the Industrial Development Administration (IDA) under the Ministry of Economic Affairs, has drawn more than 21,000 applicants. As of July 2026, 8,464 people had been certified.", "The entry-level exam is held four times a year and the intermediate level twice a year, with average pass rates of 40 to 50 percent. IDA Director-General Chiou Chyou-huey said the number of applicants reflects market demand and that AI has become the hottest field. The program focuses on practical use of AI tools rather than advanced development skills.", "The government plans to train about 1,000 AI consultants and help 14,000 businesses adopt AI over the next two years, with subsidies for consulting services. It aims to raise AI adoption in manufacturing from about 6 to 7 percent today to 50 percent by 2028."], "ar": ["استقطبت شهادة \"مخطط تطبيقات الذكاء الاصطناعي\" في تايوان، التي أطلقتها إدارة التنمية الصناعية (IDA) التابعة لوزارة الشؤون الاقتصادية عام 2025، أكثر من 21,000 متقدم. وحتى يوليو 2026، حصل 8,464 شخصًا على الشهادة.", "يُعقد اختبار المستوى المبتدئ أربع مرات سنويًا، والمستوى المتوسط مرتين سنويًا، ويبلغ متوسط نسب النجاح ما بين 40 و50 في المئة. وقال المدير العام للإدارة Chiou Chyou-huey إن عدد المتقدمين يعكس طلب السوق، وإن الذكاء الاصطناعي أصبح المجال الأكثر رواجًا. ويركز البرنامج على الاستخدام العملي لأدوات الذكاء الاصطناعي بدلًا من مهارات التطوير المتقدمة.", "تعتزم الحكومة تدريب نحو 1,000 مستشار في مجال الذكاء الاصطناعي ومساعدة 14,000 شركة على تبنّيه خلال العامين المقبلين، مع تقديم دعم لخدمات الاستشارات. وتهدف إلى رفع نسبة تبنّي الذكاء الاصطناعي في قطاع التصنيع من نحو 6 إلى 7 في المئة حاليًا إلى 50 في المئة بحلول عام 2028."], "zh-TW": ["經濟部產業發展署於2025年推出的「AI應用規劃師」能力鑑定，報名人數已突破2萬1千人。截至2026年7月，已有8,464人取得證照。", "初級考試每年舉辦四次，中級每年舉辦兩次，平均通過率約40%至50%。產發署署長邱求慧表示，報名人數反映了市場需求所在，AI已成為最熱門的領域。此鑑定著重於AI工具的實務應用，而非進階開發技能。", "政府計畫在未來兩年培訓約1,000名AI顧問，協助1萬4千家企業導入AI，並補助顧問輔導服務。目標是將製造業的AI導入率由目前約6%至7%提升至2028年的50%。"], "zh-CN": ["台湾“经济部”产业发展署于2025年推出的“AI应用规划师”能力鉴定，报名人数已突破2.1万人。截至2026年7月，已有8,464人获得证书。", "初级考试每年举办四次，中级每年举办两次，平均通过率约为40%至50%。产发署署长邱求慧表示，报名人数反映了市场需求所在，AI已成为最热门的领域。该鉴定注重AI工具的实际应用，而非高级开发技能。", "当局计划在未来两年培训约1,000名AI顾问，协助1.4万家企业导入AI，并为咨询服务提供补贴。目标是将制造业的AI导入率从目前约6%至7%提高到2028年的50%。"], "ms": ["Pensijilan perancang aplikasi AI Taiwan, yang dilancarkan pada 2025 oleh Industrial Development Administration (IDA) di bawah Kementerian Hal Ehwal Ekonomi, telah menarik lebih 21,000 pemohon. Sehingga Julai 2026, seramai 8,464 orang telah diperakui.", "Peperiksaan peringkat permulaan diadakan empat kali setahun dan peringkat pertengahan dua kali setahun, dengan kadar lulus purata 40 hingga 50 peratus. Ketua Pengarah IDA, Chiou Chyou-huey, berkata jumlah pemohon mencerminkan permintaan pasaran dan AI kini menjadi bidang paling popular. Program ini memberi tumpuan kepada penggunaan praktikal alat AI, bukan kemahiran pembangunan lanjutan.", "Kerajaan merancang untuk melatih kira-kira 1,000 perunding AI dan membantu 14,000 perniagaan menggunakan AI dalam tempoh dua tahun akan datang, dengan subsidi untuk perkhidmatan perundingan. Sasarannya ialah meningkatkan penggunaan AI dalam sektor pembuatan daripada kira-kira 6 hingga 7 peratus kini kepada 50 peratus menjelang 2028."]}}, {"date": "2026-07-03", "source": "https://www.taiwannews.com.tw/news/6394643", "body": {"en": ["Taiwanese power semiconductor maker Panjit International is expanding its product range to meet demand from electric vehicles, AI computing, and industrial automation and robotics. Power semiconductors convert, distribute and protect electrical power in electronic systems.", "For the automotive market, Panjit offers automotive-grade components for battery management systems, vehicle safety and control functions, supporting uses such as smart cockpits and 48-volt vehicle architectures. It is also developing silicon carbide solutions, which handle higher voltages and heat with lower power loss than traditional silicon.", "For AI, the company offers specialised MOSFETs and advanced packaging for power delivery in AI servers, which consume large amounts of energy. Panjit has also developed an integrated motor control solution that combines a microcontroller and a MOSFET in a single package for robotic and industrial applications."], "ar": ["توسّع شركة Panjit International التايوانية المصنّعة لأشباه موصلات الطاقة نطاق منتجاتها لتلبية الطلب من قطاعات السيارات الكهربائية وحوسبة الذكاء الاصطناعي والأتمتة الصناعية والروبوتات. وتتولى أشباه موصلات الطاقة تحويل الطاقة الكهربائية وتوزيعها وحمايتها في الأنظمة الإلكترونية.", "في سوق السيارات، تقدّم Panjit مكونات بمواصفات السيارات لأنظمة إدارة البطاريات ووظائف السلامة والتحكم في المركبات، بما يدعم تطبيقات مثل قمرات القيادة الذكية وبنى المركبات بجهد 48 فولت. كما تطوّر حلولًا من كربيد السيليكون تتحمل جهدًا وحرارة أعلى مع فقد أقل للطاقة مقارنة بالسيليكون التقليدي.", "وفي مجال الذكاء الاصطناعي، تقدّم الشركة ترانزستورات MOSFET متخصصة وتقنيات تغليف متقدمة لأنظمة إمداد الطاقة في خوادم الذكاء الاصطناعي التي تستهلك كميات كبيرة من الطاقة. كما طوّرت Panjit حلًا متكاملًا للتحكم في المحركات يجمع بين متحكم دقيق وترانزستور MOSFET في حزمة واحدة للتطبيقات الروبوتية والصناعية."], "zh-TW": ["台灣功率半導體廠強茂（Panjit International）正擴展產品組合，以因應電動車、AI運算及工業自動化與機器人領域的需求。功率半導體負責電子系統中電力的轉換、分配與保護。", "在車用市場，強茂提供車規級元件，應用於電池管理系統、行車安全及控制功能，支援智慧座艙與48伏特車輛架構等應用。公司也在發展碳化矽解決方案，相較傳統矽材料，可承受更高電壓與溫度，並降低功率損耗。", "在AI領域，公司提供專用MOSFET及先進封裝技術，用於耗電量龐大的AI伺服器供電系統。強茂亦開發整合式馬達控制方案，將微控制器與MOSFET整合於單一封裝，供機器人及工業應用使用。"], "zh-CN": ["台湾功率半导体厂商强茂（Panjit International）正在扩展产品组合，以满足电动汽车、AI计算以及工业自动化与机器人领域的需求。功率半导体负责电子系统中电力的转换、分配和保护。", "在汽车市场，强茂提供车规级元器件，用于电池管理系统、行车安全及控制功能，支持智能座舱和48伏汽车架构等应用。公司还在开发碳化硅解决方案，与传统硅材料相比，可承受更高的电压和温度，并降低功率损耗。", "在AI领域，公司提供专用MOSFET和先进封装技术，用于耗电量巨大的AI服务器供电系统。强茂还开发了集成式电机控制方案，将微控制器与MOSFET集成在单一封装中，面向机器人和工业应用。"], "ms": ["Pengeluar semikonduktor kuasa Taiwan, Panjit International, sedang meluaskan rangkaian produknya untuk memenuhi permintaan daripada kenderaan elektrik, pengkomputeran AI, serta automasi industri dan robotik. Semikonduktor kuasa berfungsi menukar, mengagih dan melindungi kuasa elektrik dalam sistem elektronik.", "Bagi pasaran automotif, Panjit menawarkan komponen gred automotif untuk sistem pengurusan bateri, keselamatan kenderaan dan fungsi kawalan, menyokong kegunaan seperti kokpit pintar dan seni bina kenderaan 48 volt. Syarikat itu juga membangunkan penyelesaian silikon karbida yang mampu menahan voltan dan haba lebih tinggi dengan kehilangan kuasa lebih rendah berbanding silikon biasa.", "Bagi AI, syarikat itu menawarkan MOSFET khusus dan pembungkusan termaju untuk sistem bekalan kuasa pelayan AI yang menggunakan tenaga yang besar. Panjit juga telah membangunkan penyelesaian kawalan motor bersepadu yang menggabungkan mikropengawal dan MOSFET dalam satu pakej untuk aplikasi robotik dan industri."]}}, {"date": "2026-03-30", "source": "https://www.bicycleretailer.com/announcements/2026/03/30/taipei-cycle-2026-concludes-definitive-global-hub-innovation", "body": {"en": ["Taipei Cycle 2026 took place from March 25 to 28 at the Taipei Nangang Exhibition Center and was organised by the Taiwan External Trade Development Council (TAITRA). Under the theme \"Cycling to Wellness\", the show featured about 900 exhibitors in 3,450 booths, including around 200 international exhibitors.", "The show was built around four pillars: Green Forward for sustainability and low-carbon manufacturing, Motion Vision for sports technology and startups, the Taipei Cycle Industry Forum, and the Taipei Cycle d&i Awards for design and innovation.", "Key topics included AI-driven sports technology, e-mobility, green urban transport, ESG-led manufacturing, gravel bikes, 32-inch wheels and smart components. Brands such as Giant, Merida, SRAM and Colnago presented new products. The show also reflected the industry's recovery from post-COVID inventory adjustments, with sales momentum returning in Europe and North America."], "ar": ["أُقيم معرض Taipei Cycle 2026 في الفترة من 25 إلى 28 مارس في مركز Nangang للمعارض في تايبيه، ونظّمه المجلس التايواني لتنمية التجارة الخارجية (TAITRA). وتحت شعار \"Cycling to Wellness\"، شارك في المعرض نحو 900 عارض في 3,450 جناحًا، من بينهم قرابة 200 عارض دولي.", "قام المعرض على أربع ركائز: \"Green Forward\" للاستدامة والتصنيع منخفض الكربون، و\"Motion Vision\" لتقنيات الرياضة والشركات الناشئة، ومنتدى Taipei Cycle للصناعة، وجوائز Taipei Cycle d&i للتصميم والابتكار.", "شملت أبرز الموضوعات تقنيات الرياضة المعتمدة على الذكاء الاصطناعي، والتنقل الكهربائي، والنقل الحضري الأخضر، والتصنيع القائم على معايير ESG، ودراجات الحصى، والعجلات مقاس 32 بوصة، والمكونات الذكية. وقدّمت علامات تجارية مثل Giant وMerida وSRAM وColnago منتجات جديدة. كما عكس المعرض تعافي القطاع من تعديلات المخزون التي أعقبت جائحة كوفيد، مع عودة زخم المبيعات في أوروبا وأمريكا الشمالية."], "zh-TW": ["2026台北國際自行車展（Taipei Cycle）於3月25日至28日在台北南港展覽館舉行，由中華民國對外貿易發展協會（TAITRA）主辦。本屆以「Cycling to Wellness」為主題，約有900家展商、使用3,450個攤位，其中國際展商約200家。", "展會圍繞四大主軸：聚焦永續與低碳製造的Green Forward、聚焦運動科技與新創的Motion Vision、台北自行車產業論壇，以及表彰設計與創新的Taipei Cycle d&i Awards。", "重點議題包括AI驅動的運動科技、電動化移動、綠色城市交通、ESG導向製造、礫石車、32吋輪組及智慧零組件。Giant、Merida、SRAM及Colnago等品牌發表新產品。展會也反映產業已從疫情後的庫存調整中復甦，歐洲與北美市場的銷售動能逐步回升。"], "zh-CN": ["2026台北国际自行车展（Taipei Cycle）于3月25日至28日在台北南港展览馆举行，由台湾对外贸易发展协会（TAITRA）主办。本届以“Cycling to Wellness”为主题，约有900家展商、使用3,450个展位，其中国际展商约200家。", "展会围绕四大主轴：聚焦可持续发展与低碳制造的Green Forward、聚焦运动科技与初创企业的Motion Vision、台北自行车产业论坛，以及表彰设计与创新的Taipei Cycle d&i Awards。", "重点议题包括AI驱动的运动科技、电动出行、绿色城市交通、ESG导向制造、砾石车、32英寸车轮及智能零部件。Giant、Merida、SRAM和Colnago等品牌发布了新产品。展会也反映出行业已从疫情后的库存调整中复苏，欧洲和北美市场的销售势头逐步回升。"], "ms": ["Taipei Cycle 2026 telah berlangsung dari 25 hingga 28 Mac di Taipei Nangang Exhibition Center dan dianjurkan oleh Taiwan External Trade Development Council (TAITRA). Dengan tema \"Cycling to Wellness\", pameran ini menampilkan kira-kira 900 pempamer di 3,450 gerai, termasuk sekitar 200 pempamer antarabangsa.", "Pameran ini dibina atas empat tonggak: Green Forward untuk kelestarian dan pembuatan rendah karbon, Motion Vision untuk teknologi sukan dan syarikat pemula, Taipei Cycle Industry Forum, serta Taipei Cycle d&i Awards untuk reka bentuk dan inovasi.", "Topik utama termasuk teknologi sukan berasaskan AI, e-mobiliti, pengangkutan bandar hijau, pembuatan berteraskan ESG, basikal gravel, roda 32 inci dan komponen pintar. Jenama seperti Giant, Merida, SRAM dan Colnago memperkenalkan produk baharu. Pameran ini juga mencerminkan pemulihan industri daripada pelarasan inventori selepas COVID, dengan momentum jualan kembali di Eropah dan Amerika Utara."]}}, {"date": null, "source": "https://www.tdspump.com/about-dyi-sheng", "body": {"en": ["TDS-DYISHENG (DYI SHENG Industry Co., Ltd.) is a Taiwanese maker of air-operated double diaphragm (AODD) pumps. Founded in 1986 and based in Taichung, the company makes all of its products in Taiwan, and every pump is performance-tested before shipment.", "Its range includes pumps in aluminium alloy, stainless steel and polypropylene, as well as solenoid-controlled pumps, accessories and spare parts. The company says its patented air valve technology gives non-stall operation with little maintenance. Products carry CE, ISO 9001 and ATEX certifications, and genuine pumps come with an 18-month global warranty.", "TDS-DYISHENG exports to more than 60 countries and serves over 20 industries, including chemical processing, mining, water treatment, pharmaceuticals, food production and metalworking. Its pumps are sold through local distributors and online channels."], "ar": ["TDS-DYISHENG (شركة DYI SHENG Industry Co., Ltd.) شركة تايوانية مصنّعة للمضخات الغشائية المزدوجة العاملة بالهواء المضغوط (AODD). تأسست عام 1986 ويقع مقرها في تايتشونغ، وتصنع جميع منتجاتها في تايوان، وتخضع كل مضخة لاختبار أداء كامل قبل الشحن.", "تضم مجموعة منتجاتها مضخات من سبائك الألومنيوم والفولاذ المقاوم للصدأ والبولي بروبيلين، إلى جانب مضخات يُتحكم بها بصمام كهرومغناطيسي، وملحقات وقطع غيار. وتقول الشركة إن تقنية صمام الهواء الحاصلة على براءة اختراع تضمن تشغيلًا دون توقف مع صيانة محدودة. وتحمل المنتجات شهادات CE وISO 9001 وATEX، وتأتي المضخات الأصلية بضمان عالمي مدته 18 شهرًا.", "تصدّر TDS-DYISHENG منتجاتها إلى أكثر من 60 دولة، وتخدم أكثر من 20 قطاعًا، منها المعالجة الكيميائية والتعدين ومعالجة المياه والصناعات الدوائية وإنتاج الأغذية وتشغيل المعادن. وتُباع مضخاتها عبر موزعين محليين وقنوات إلكترونية."], "zh-TW": ["TDS-DYISHENG（DYI SHENG Industry Co., Ltd.）是台灣的氣動雙隔膜泵（AODD）製造商。公司創立於1986年，總部位於台中，所有產品皆在台灣製造，每台泵浦出貨前均經過完整性能測試。", "產品線包括鋁合金、不鏽鋼及聚丙烯材質的泵浦，以及電磁閥控制泵浦、配件與備品。公司表示，其專利氣閥技術可實現不停機運轉，且維護需求低。產品通過CE、ISO 9001及ATEX認證，正品泵浦享有18個月全球保固。", "TDS-DYISHENG產品外銷超過60個國家，服務逾20個產業，包括化工、礦業、水處理、製藥、食品生產及金屬加工。其泵浦透過各地經銷商及線上通路銷售。"], "zh-CN": ["TDS-DYISHENG（DYI SHENG Industry Co., Ltd.）是台湾的气动双隔膜泵（AODD）制造商。公司成立于1986年，总部位于台中，所有产品均在台湾制造，每台泵出货前都经过完整的性能测试。", "产品线包括铝合金、不锈钢和聚丙烯材质的泵，以及电磁阀控制泵、配件和备件。公司表示，其专利气阀技术可实现不停机运行，且维护需求低。产品通过CE、ISO 9001和ATEX认证，正品泵享有18个月全球质保。", "TDS-DYISHENG的产品出口到60多个国家，服务20多个行业，包括化工、采矿、水处理、制药、食品生产和金属加工。其泵通过各地经销商和线上渠道销售。"], "ms": ["TDS-DYISHENG (DYI SHENG Industry Co., Ltd.) ialah pengeluar pam diafragma berganda kendalian udara (AODD) dari Taiwan. Diasaskan pada 1986 dan berpangkalan di Taichung, syarikat ini mengeluarkan semua produknya di Taiwan, dan setiap pam diuji prestasinya sebelum dihantar.", "Rangkaian produknya termasuk pam aloi aluminium, keluli tahan karat dan polipropilena, serta pam kawalan solenoid, aksesori dan alat ganti. Syarikat itu menyatakan bahawa teknologi injap udara berpatennya membolehkan operasi tanpa terhenti dengan penyelenggaraan yang minimum. Produknya memiliki pensijilan CE, ISO 9001 dan ATEX, dan pam tulen disertakan jaminan global selama 18 bulan.", "TDS-DYISHENG mengeksport ke lebih 60 negara dan berkhidmat kepada lebih 20 industri, termasuk pemprosesan kimia, perlombongan, rawatan air, farmaseutikal, pengeluaran makanan dan kerja logam. Pamnya dijual melalui pengedar tempatan dan saluran dalam talian."]}}, {"date": "2026-07-04", "source": "https://www.taipeitimes.com/News/biz/archives/2026/07/04/2003860191", "body": {"en": ["Nitto Denko (Taiwan) Corporation inaugurated its new plant in Kaohsiung's Cianjhen Technology Industrial Park on July 3, 2026. The company invested NT$4.48 billion (about US$140 million) in the project, which includes a manufacturing facility and a research and development building.", "The site will produce PVC sheets and tapes, electronic adhesive tapes and other high-performance materials for semiconductor and automotive customers. The plant is expected to add about NT$200 million to annual revenue. Construction began in December 2024, with the aim of strengthening Taiwan's role as a key Asia-Pacific production hub for the Nitto Group.", "Nitto Denko (Taiwan) is in its 57th year of operations. At the ceremony, Liu Chi-chuan, deputy director-general of the Bureau of Industrial Parks, said Japan has long been one of Taiwan's key trading and investment partners."], "ar": ["افتتحت شركة Nitto Denko (Taiwan) Corporation مصنعها الجديد في منطقة Cianjhen للصناعات التقنية في كاوهسيونغ في 3 يوليو 2026. واستثمرت الشركة 4.48 مليار دولار تايواني جديد (نحو 140 مليون دولار أمريكي) في المشروع، الذي يضم منشأة تصنيع ومبنى للبحث والتطوير.", "سينتج الموقع ألواحًا وأشرطة من PVC، وأشرطة لاصقة إلكترونية، ومواد أخرى عالية الأداء لعملاء قطاعي أشباه الموصلات والسيارات. ومن المتوقع أن يضيف المصنع نحو 200 مليون دولار تايواني جديد إلى الإيرادات السنوية. وبدأ البناء في ديسمبر 2024 بهدف تعزيز دور تايوان بوصفها مركز إنتاج رئيسيًا لمجموعة Nitto في منطقة آسيا والمحيط الهادئ.", "تدخل Nitto Denko (Taiwan) عامها السابع والخمسين من العمل. وخلال حفل الافتتاح، قال Liu Chi-chuan، نائب المدير العام لمكتب المناطق الصناعية، إن اليابان تُعد منذ زمن طويل أحد أهم الشركاء التجاريين والاستثماريين لتايوان."], "zh-TW": ["台灣日東電工（Nitto Denko (Taiwan) Corporation）於2026年7月3日在高雄前鎮科技產業園區為新廠舉行落成典禮。公司投資新台幣44.8億元（約1.4億美元），新廠包含生產廠房及研發大樓。", "新廠將生產PVC膠布與膠帶、電子用黏著膠帶，以及供半導體與車用客戶使用的其他高性能材料，預計每年可增加約新台幣2億元營收。該廠於2024年12月動工，目標是強化台灣作為日東集團亞太區重要生產基地的地位。", "台灣日東電工已邁入營運第57年。經濟部產業園區管理局副局長劉季川在典禮上表示，日本長期以來是台灣重要的貿易與投資夥伴之一。"], "zh-CN": ["台湾日东电工（Nitto Denko (Taiwan) Corporation）于2026年7月3日在高雄前镇科技产业园区为新厂举行落成典礼。公司投资新台币44.8亿元（约1.4亿美元），新厂包括生产厂房和研发大楼。", "新厂将生产PVC片材与胶带、电子用胶粘带，以及供半导体和汽车客户使用的其他高性能材料，预计每年可增加约新台币2亿元营收。该厂于2024年12月动工，目标是加强台湾作为日东集团亚太地区重要生产基地的地位。", "台湾日东电工已进入运营第57年。产业园区管理局副局长刘季川在典礼上表示，日本长期以来是台湾重要的贸易和投资伙伴之一。"], "ms": ["Nitto Denko (Taiwan) Corporation telah merasmikan kilang baharunya di Cianjhen Technology Industrial Park, Kaohsiung, pada 3 Julai 2026. Syarikat itu melabur NT$4.48 bilion (kira-kira US$140 juta) dalam projek ini, yang merangkumi kemudahan pembuatan dan bangunan penyelidikan dan pembangunan.", "Tapak ini akan mengeluarkan kepingan dan pita PVC, pita pelekat elektronik dan bahan berprestasi tinggi lain untuk pelanggan semikonduktor dan automotif. Kilang ini dijangka menambah kira-kira NT$200 juta kepada hasil tahunan. Pembinaan bermula pada Disember 2024 dengan matlamat mengukuhkan peranan Taiwan sebagai hab pengeluaran utama Asia Pasifik bagi Kumpulan Nitto.", "Nitto Denko (Taiwan) kini berada dalam tahun operasi ke-57. Pada majlis itu, Liu Chi-chuan, timbalan ketua pengarah Bureau of Industrial Parks, berkata Jepun sejak sekian lama merupakan salah satu rakan dagangan dan pelaburan utama Taiwan."]}}];
